#include <vector>
#include <omp.h>
#include <algorithm>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.resize(n);
    if (n == 0) return;

    // We compute suffix sums: output[i] = sum_{k=i}^{n-1} x[k]
    // Use a two-phase parallel scheme:
    // 1) Each thread computes suffix sums within its block (from right to left),
    //    and records the block total.
    // 2) Compute offsets for each block from totals to the right, then add offsets.
    int nthreads = 1;
    std::vector<long long> blockSum; // per-thread block totals (avoid overflow in intermediate sums)

#pragma omp parallel
    {
#pragma omp single
        {
            nthreads = omp_get_num_threads();
            blockSum.assign(nthreads, 0LL);
        }

        const int tid = omp_get_thread_num();

        // Static block partitioning of indices [0, n)
        const int chunk = (n + nthreads - 1) / nthreads;
        int begin = tid * chunk;
        int end = std::min(n, begin + chunk); // [begin, end)

        long long local = 0;
        if (begin < end) {
            // Compute local suffix sums inside the block, right-to-left.
            for (int i = end - 1; i >= begin; --i) {
                local += static_cast<long long>(x[i]);
                output[i] = static_cast<int>(local);
            }
        }
        blockSum[tid] = local;

#pragma omp barrier

        // Compute per-block offset = sum of all blockSum for blocks to the right.
        // Done by a single thread to avoid races (cost is O(nthreads)).
        static std::vector<long long> offset;
#pragma omp single
        {
            offset.assign(nthreads, 0LL);
            long long run = 0;
            for (int t = nthreads - 1; t >= 0; --t) {
                offset[t] = run;
                run += blockSum[t];
            }
        }

#pragma omp barrier

        const long long add = offset[tid];
        if (begin < end && add != 0) {
            for (int i = begin; i < end; ++i) {
                output[i] = static_cast<int>(static_cast<long long>(output[i]) + add);
            }
        }
    }
}
